      "visual_concept": "A peaceful, smiling baby sleeping soundly on a stylized, fluffy white cloud. The background features soft pastel blues and warm yellows.",
      "headline": "Like a Hug from a Cloud.",
      "subheadline": "The ultimate comfort your baby deserves.",
      "body_copy": "You want the absolute best for your baby, and so do we. Introducing CloudBum Diapers, crafted with ultra-plush, breathable materials that move gently with your little one. Say goodbye to red marks, scratchy tabs, and irritation. With CloudBum, you get pure, 360-degree comfort that keeps your baby playing happily all day and sleeping soundly all night.",
      "call_to_action": "Shop the comfort. Get 20% off your first month's supply at CloudBum.com"
    },
    "social_media_video_ad": {
      "platforms": [
        "Instagram",
        "TikTok",
        "Facebook"
      ],
      "video_sequence": [
        "0:00 - 0:02: Close up of a fussy baby pulling at a standard, stiff diaper.",
        "0:02 - 0:05: Text overlay 'Time for a comfort upgrade?' with a magical swoosh transition.",
        "0:05 - 0:10: Baby is now wearing a CloudBum diaper, giggling and crawling freely. Close-up macro shot of the ultra-soft, pillowy inner lining.",
        "0:10 - 0:15: Happy baby fast asleep. Text overlay 'Cloud-like comfort for uninterrupted dreams.'"
      ],
      "caption": "Is a scratchy diaper interrupting your baby's playtime? ☁️ Upgrade to CloudBum for 360-degree softness and breathable comfort! Watch them move, play, and sleep with zero irritation. Tap the link to claim your free trial pack today! 👶💤",
      "hashtags": [
        "#CloudBum",
        "#BabyComfort",
        "#HappyBaby",
        "#ParentingHacks",
        "#MomLife",
        "#DadLife",
        "#GentleOnSkin"
      ]
    },
    "search_engine_text_ad": {
      "headline_1": "The Most Comfortable Diapers",
      "headline_2": "CloudBum Ultra-Soft Fit",
      "headline_3": "Claim Your Free Trial",
      "description": "Stop diaper chafing and red marks. Our breathable, cloud-soft diapers move with your baby for ultimate day and night comfort. Order today for 20% off!"
    }
  }
}

{
  "campaign_details": {
    "product_name": "CloudBums Diapers",
    "core_focus": "Maximum comfort for babies",
    "target_audience": "Parents and caregivers of infants and toddlers who prioritize their child's comfort and skin health."
  },
  "key_selling_points": [
    "Cloud-soft, hypoallergenic inner layer to prevent chafing",
    "360-degree flexible waistband that moves with active babies",
    "Breathable micro-pore technology to keep skin dry and rash-free",
    "Feather-light feel without sacrificing 12-hour leak protection"
  ],
  "advertisements": {
    "social_media_ad": {
      "platform": "Instagram & Facebook",
      "visual_concept": "A softly lit, high-quality photo of a baby sleeping peacefully on a plush white rug, wearing only the CloudBums diaper.",
      "headline": "Like a hug from a cloud. ☁️",
      "body_copy": "Say goodbye to red marks and fussiness! Introducing CloudBums—the diaper designed entirely around your baby's comfort. Made with ultra-soft, breathable materials and a waistband that stretches with every wiggle, your little one will feel like they are wearing nothing at all. Because a comfortable baby means a happy parent. 👶✨",
      "call_to_action": "Get 20% off your first month's supply! [Link]",
      "hashtags": [
        "#CloudBums",
        "#BabyComfort",
        "#HappyBaby",
        "#ParentingHacks"
      ]
    },
    "video_ad_script": {
      "platform": "YouTube & TikTok",
      "duration": "15 seconds",
      "scenes": [
        {
          "time": "0:00 - 0:03",
          "visual": "Close-up of a baby giggling and crawling towards the camera.",
          "audio": "Upbeat, gentle acoustic guitar music begins."
        },
        {
          "time": "0:03 - 0:08",
          "visual": "3D animation showing the diaper's layers. A feather lands on the inner lining, emphasizing softness.",
          "audio_voiceover": "Your baby's skin is delicate. Shouldn't their diaper be too?"
        },
        {
          "time": "0:08 - 0:12",
          "visual": "Baby sleeping soundly in a crib. Parent gently strokes their cheek.",
          "audio_voiceover": "Meet CloudBums. Unbeatable leak protection wrapped in cloud-like softness."
        },
        {
          "time": "0:12 - 0:15",
          "visual": "CloudBums logo appears on screen with a 'Shop Now' button.",
          "audio_voiceover": "CloudBums. The comfort they deserve."
        }
      ]
    },
    "email_marketing": {
      "subject_line": "☁️ The diaper upgrade your baby has been dreaming of...",
      "preview_text": "Discover the ultimate comfort with CloudBums diapers.",
      "body": "Hi [Parent Name],\n\nWe know that when your baby is uncomfortable, nobody sleeps. That's why we reimagined the diaper from the ground up.\n\nIntroducing CloudBums: engineered for ultimate comfort. We ditched the stiff, scratchy materials and replaced them with hypoallergenic, breathable layers that feel as soft as your favorite t-shirt. \n\nWhether they are taking their first steps or taking a much-needed nap, CloudBums moves with them, preventing leaks and protecting their delicate skin.\n\nReady to feel the difference?",
      "button_text": "Claim Your Free Trial Pack"
    }
  }
}

{
  "advertisement_campaign": {
