            System.out.println("Waiting for a client to connect...");
            System.out.println("==========================================");

            // Accept incoming connection
            Socket clientSocket = serverSocket.accept();
            System.out.println("Client connected from IP: " + clientSocket.getInetAddress().getHostAddress());

            // Set up input and output streams
            BufferedReader in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
            PrintWriter out = new PrintWriter(clientSocket.getOutputStream(), true);

            String message;
            // Read incoming messages from client until 'exit' is received
            while ((message = in.readLine()) != null) {
                if ("exit".equalsIgnoreCase(message.trim())) {
                    System.out.println("Client requested disconnection.");
                    out.println("Connection closed by server.");
                    break;
                }
                System.out.println("Received from client: " + message);
                // Echo the message back to the client
                out.println("Server Echo: " + message);
            }

            // Close connection
