To capture a window or screen directly into a memory buffer in C++ on Windows, you can use the Windows Graphics Device Interface (GDI) API. 

The process involves capturing the window's Device Context (DC) into a bitmap and extracting the raw pixel bytes into a `std::vector<BYTE>` using `GetDIBits`.

Here is a complete, self-contained example:

### C++ Example (Windows GDI)

```cpp
#include <windows.h>
#include <vector>
#include <iostream>

struct ScreenshotData {
    int width = 0;
    int height = 0;
    int channels = 4; // BGRA (32-bit)
    std::vector<BYTE> pixels;
};

// Captures a specified window (or pass NULL / GetDesktopWindow() for entire screen)
bool CaptureWindowToMemory(HWND hwnd, ScreenshotData& outData) {
    if (!hwnd) {
        hwnd = GetDesktopWindow();
    }

    // 1. Get window dimensions
    RECT rc;
    GetClientRect(hwnd, &rc);
    int width = rc.right - rc.left;
    int height = rc.bottom - rc.top;

    if (width <= 0 || height <= 0) return false;

    // 2. Create device contexts
    HDC hdcWindow = GetDC(hwnd);
    HDC hdcMem = CreateCompatibleDC(hdcWindow);

    // 3. Create compatible bitmap
    HBITMAP hBitmap = CreateCompatibleBitmap(hdcWindow, width, height);
    HGDIOBJ hOldBitmap = SelectObject(hdcMem, hBitmap);

    // 4. Copy the image from the window to the memory DC
    // Note: Use PrintWindow for background/covered windows, or BitBlt for active screen capture
    BOOL success = PrintWindow(hwnd, hdcMem, PW_RENDERFULLCONTENT);
    if (!success) {
        // Fallback to BitBlt if PrintWindow fails
        BitBlt(hdcMem, 0, 0, width, height, hdcWindow, 0, 0, SRCCOPY);
    }

    // 5. Configure bitmap info to read raw pixel data
    BITMAPINFOHEADER bi = {};
    bi.biSize = sizeof(BITMAPINFOHEADER);
    bi.biWidth = width;
    bi.biHeight = -height; // Negative height indicates top-down bitmap
    bi.biPlanes = 1;
    bi.biBitCount = 32;    // 32-bit BGRA format
    bi.biCompression = BI_RGB;

    // Allocate memory buffer (width * height * 4 bytes per pixel)
    outData.width = width;
    outData.height = height;
