Here's an example of how you might write a simple script in Node.js to check if two interfaces are compatible:
```javascript
const ts = require('typescript');

function compareInterfaces(interface1, interface2) {
    const sourceFile1 = ts.createSourceFile('interface1.ts', interface1, ts.ScriptTarget.ES2015);
    const sourceFile2 = ts.createSourceFile('interface2.ts', interface2, ts.ScriptTarget.ES2015);

    const interface1Properties = sourceFile1.statements.filter(statement => statement.kind === ts.SyntaxKind.PropertyDeclaration);
    const interface2Properties = sourceFile2.statements.filter(statement => statement.kind === ts.SyntaxKind.PropertyDeclaration);

    for (const property1 of interface1Properties) {
        const property2 = interface2Properties.find(p => p.name.text === property1.name.text);
        if (!property2) {
            return false;
        }
    }

    for (const property2 of interface2Properties) {
        const property1 = interface1Properties.find(p => p.name.text === property2.name.text);
        if (!property1) {
            return false;
        }
    }

    return true;
}

// Example usage
const interface1 = 'interface Interface1 { foo: number; }';
const interface2 = 'interface Interface2 { foo: string; }';

if (compareInterfaces(interface1, interface2)) {
    console.log('Interfaces are compatible');
} else {
    console.log('Interfaces are not compatible');
}
```
