**Encryption using OpenSSL (Sender)**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/rand.h>

// Function to encrypt a message using AES-256-CBC
unsigned char* aes_encrypt(const char* message, int message_length) {
    unsigned char* encrypted_message = malloc(message_length + 16); // 16 bytes for padding and IV
    unsigned char iv[16];
    AES_KEY aes_key;

    // Generate a random IV
    RAND_bytes(iv, 16);

    // Initialize the AES key
    AES_set_encrypt_key((unsigned char*)message, 256, &aes_key);

    // Encrypt the message
    AES_cbc_encrypt((const unsigned char*)message, encrypted_message, message_length, &aes_key, iv, AES_ENCRYPT);

    // Return the encrypted message with the IV prepended
    return malloc(message_length + 16);
}

int main() {
    const char* message = "Hello, World!";
    int message_length = strlen(message);

    unsigned char* encrypted_message = aes_encrypt(message, message_length);

    // Print the encrypted message
    printf("Encrypted message (with IV): ");
    for (int i = 0; i < message_length + 16; i++) {
        printf("%02x ", encrypted_message[i]);
    }
    printf("\n");

    free(encrypted_message);

    return 0;
}
```

**Decryption using Microsoft CryptoAPI (Recipient)**

This example uses the Microsoft CryptoAPI to decrypt the encrypted message. Please note that this requires the Microsoft Visual Studio environment and the `mscrypt` library.

```cpp
#include <Windows.h>
#include <mscrypt.h>
#include <iostream>

// Function to decrypt a message using AES-256-CBC
void aes_decrypt(unsigned char* encrypted_message, int encrypted_message_length, char* decrypted_message) {
    unsigned char iv[16];
    unsigned char* decrypted_message_ptr = (unsigned char*)decrypted_message;
    AES_KEY aes_key;

    // Copy the IV from the encrypted message
    memcpy(iv, encrypted_message, 16);

    // Initialize the AES key
    AES_set_decrypt_key((const unsigned char*)encrypted_message, 256, &aes_key);

    // Decrypt the message
    AES_cbc_encrypt((const unsigned char*)encrypted_message, decrypted_message_ptr, encrypted_message_length, &aes_key, iv, AES_DECRYPT);

    // Print the decrypted message
    std::cout << "Decrypted message: " << decrypted_message << std::endl;
}

int main() {
    const char* encrypted_message = "Your encrypted message here";
    int encrypted_message_length = strlen(encrypted_message);

    char decrypted_message[256];

    aes_decrypt(encrypted_message, encrypted_message_length, decrypted_message);

    return 0;
}
```

**Notes**

*   To compile the OpenSSL code, use the following command: `gcc -o aes_example aes_example.c -lcrypto -lssl -o aes_example.exe`
*   To compile the Microsoft CryptoAPI code, use the following command in Visual Studio: `cl /c /link /lib:mscrypt /link /lib user32.lib mpr.lib aes_example.cpp`
*   The encrypted message from the OpenSSL code should be base64-encoded before passing it to the Microsoft CryptoAPI code for decryption.
*   This example uses a fixed IV for simplicity; in a real-world scenario, you should use a random IV and store it securely for use in decryption.

