// Function to encrypt the message
void encrypt(const char *message, const char *key, char **encrypted_message) {
    AES_KEY aes_key;
    AES_set_encrypt_key((const unsigned char *)key, 128, &aes_key);

    unsigned char encrypted_message[1024]; // assume the message size is less than 1024 bytes

    AES_cbc_encrypt((const unsigned char *)message, encrypted_message, 1024, &aes_key, NULL, 128);

    *encrypted_message = encrypted_message[0];
    *encrypted_message = encrypted_message[1];
