    *encrypted_message = (char *)encrypted_message + strlen(*encrypted_message);
    *encrypted_message = (char *)encrypted_message + 1024;

    // print the encrypted message
    printf("%s\n", *encrypted_message);
}

// Function to decrypt the message
void decrypt(const char *encrypted_message, const char *key, char **decrypted_message) {
    AES_KEY aes_key;
    AES_set_decrypt_key((const unsigned char *)key, 128, &aes_key);

    unsigned char decrypted_message[1024]; // assume the message size is less than 1024 bytes
    AES_cbc_encrypt((const unsigned char *)encrypted_message, decrypted_message, 1024, &aes_key, NULL, 128);

    *decrypted_message = decrypted_message[0];
    *decrypted_message = decrypted_message[1];
    *decrypted_message = '\0';

    *decrypted_message = (char *)decrypted_message + strlen(*decrypted_message);
    *decrypted_message = (char *)decrypted_message + 1024;

    // print the decrypted message
    printf("%s\n", *decrypted_message);
}

int main() {
