// Function to decrypt the message
void decrypt(const char *encrypted_message, const char *key, char **decrypted_message) {
    PRGKEY key_context;
    CRYPTO_KEY context;

    // initialize the key context
    PRGKEY_InitKeyEx(&key_context, NULL, key, 0, 0, 0, 0, 0, 0, 0);

    // initialize the context
    CRYPTO_KEY_InitEx(&context, &key_context, 0, 0, 0, 0, 0, 0, 0, 0);

    // decrypt the message
    BYTE *decrypted_message = (BYTE *)malloc(1024); // assume the message size is less than 1024 bytes
    CryptDecrypt((LPBYTE)encrypted_message, 1024, &context, 0, decrypted_message, 1024);

    // print the decrypted message
    printf("%s\n", (char *)decrypted_message);

    // free the memory
    FreeLibraryAndExitThread(NULL, 0);

    return;
}

int main() {
    const char *message = "Hello, World!";
    const char *key = "my_secret_key";
    char *encrypted_message;
    char *decrypted_message;

    decrypt((char *)message, (char *)key, &decrypted_message);

    return 0;
}
```

Note that these examples are simplified and are not intended for production use. In a real-world application, you should handle errors more robustly and use a secure way to store and manage your encryption keys.

Also, please note that Microsoft CryptoAPI is a deprecated API and should not be used for new development.

