    (void)memcpy(encrypted_message, key, 13); // assume encrypted message is 13 bytes long

    // Decrypt the message
    unsigned char* decrypted_message = (unsigned char*)malloc(256);
    CryptCreateHash(hCryptProv, CALG_AES_128_CBC, 0, 0, &hCryptHash);
    CryptSetKeyParam(hCryptHash, KEY parameter, &key, 0, 0);
    CryptSetKeyParam(hCryptHash, KEY parameter, &iv, 0, 0);
    CryptDecrypt(hCryptHash, encrypted_message, 13, decrypted_message, 13);

    // Print the decrypted message
    for (int i = 0; i < 13; i++) {
