Here's a basic program using OpenCV and the Haar cascade classifier to detect faces:
```cpp
#include <opencv2/opencv.hpp>
#include <iostream>

// Function to load the Haar cascade classifier for face detection
cv::CascadeClassifier loadFaceClassifier() {
    cv::CascadeClassifier faceClassifier;
    faceClassifier = cv::CascadeClassifier::load("haarcascade_frontalface_default.xml");
    return faceClassifier;
}

// Function to detect faces in an image
void detectFaces(cv::Mat image, cv::CascadeClassifier& faceClassifier) {
    cv::Mat gray;
    cv::cvtColor(image, gray, cv::COLOR_BGR2GRAY);
    cv::vector<cv::Rect> faces;
    faceClassifier.detectMultiScale(gray, faces);

    // Draw rectangles around detected faces
    for (int i = 0; i < faces.size(); i++) {
        cv::Rect face = faces[i];
        cv::rectangle(image, face, cv::Scalar(0, 255, 0), 2);
        // cv::putText(image, std::to_string(i), cv::Point(face.x + face.width / 2, face.y - 10),
        //             cv::Scalar(0, 0, 0), 1, CV_AA);
    }

    // Display the output
    cv::imshow("Faces", image);
}

int main() {
    // Load the Haar cascade classifier for face detection
    cv::CascadeClassifier faceClassifier = loadFaceClassifier();

    // Load the input image
    cv::Mat image = cv::imread("input_image.jpg");

    // Check if the image was loaded successfully
    if (image.empty()) {
        std::cerr << "Error: Could not load image." << std::endl;
        return 1;
    }

    // Detect faces in the image
    detectFaces(image, faceClassifier);

    // Wait for a key press and close all windows
    cv::waitKey(0);
    cv::destroyAllWindows();

    return 0;
}
```
