I'd be happy to provide a basic C++ program for facial detection, but I must clarify that facial detection is typically performed using computer vision libraries such as OpenCV, which provides a wide range of pre-trained models and algorithms for facial detection.

That being said, here's a simplified example using OpenCV and a basic face detection algorithm. This program will display a window with a video feed and detect faces in real-time.

**Note:** This is a simplified example and may not produce accurate results for all cases.

**Required Dependencies:**

* OpenCV (version 3.x or higher)
* C++ compiler (e.g., GCC)

**Program:**
```cpp
#include <opencv2/opencv.hpp>
#include <iostream>

int main() {
    // Initialize OpenCV
    cv::namedWindow("Facial Detection", cv::WINDOW_NORMAL);
    cv::resizeWindow("Facial Detection", 640, 480);

    // Create a video capture object
    cv::VideoCapture cap(0); // 0 is the default camera index

    if (!cap.isOpened()) {
        std::cerr << "Error: unable to open camera" << std::endl;
        return 1;
    }

    while (true) {
        // Read a frame from the camera
        cv::Mat frame;
        cap >> frame;

        if (frame.empty()) {
            std::cerr << "Error: unable to read frame" << std::endl;
            break;
        }

        // Convert the frame to grayscale
        cv::Mat gray;
        cv::cvtColor(frame, gray, cv::COLOR_BGR2GRAY);

        // Apply a Gaussian blur to the grayscale image
        cv::Mat blurred;
        cv::GaussianBlur(gray, blurred, cv::Size(5, 5), 0);

        // Apply a face detection algorithm (simple edge detection)
        cv::Mat contours;
        cv::findContours(blurred, contours, cv::RETR_EXTERNAL, cv::CHAIN_APPROX_SIMPLE);

        for (auto& contour : contours) {
            // Calculate the area of the contour
            cv::Rect rect = cv::boundingRect(contour);
            cv::Rect face_rect = cv::getRectSubPix(blurred, rect);

            // Draw a rectangle around the face
            cv::rectangle(frame, face_rect, cv::Scalar(0, 255, 0), 2, cv::LINE_AA);

            // Draw a text label above the face
            cv::putText(frame, "Face detected!", cv::Point(face_rect.x - 10, face_rect.y - 20), cv::FONT_HERSHEY_SIMPLEX, 0.5, cv::Scalar(0, 0, 255), 2);
        }

        // Display the frame
        cv::imshow("Facial Detection", frame);

        // Exit on key press
        if (cv::waitKey(1) == 27) {
            break;
        }
    }

    // Release resources
    cap.release();
    cv::destroyAllWindows();

    return 0;
}
```
